// Test file for assessments_models.dart (and its generated files).
//
// This file doesn't contain too many tests, since most of the code is
// generated by the freezed library and is trivial. Testing should focus on
// testing non-trivial code.

import 'package:decision_support_tool/data/static_data_models.dart';
import 'package:flutter_test/flutter_test.dart';

import '../../testing/testing_helpers.dart';
import '../../testing/testing_values.dart';

void main() {
  test('StaticData.assessmentInfoPairsSorted', () {
    final List<
      ({StaticData staticData, List<(String, AssessmentInfo)> expected})
    >
    testCases = [
      (
        staticData: StaticData(
          assessmentInfoMap: {},
          questionInfoMap: {},
          recommendationsInfoMap: {},
        ),
        expected: [],
      ),
      (
        staticData: StaticData(
          assessmentInfoMap: {
            'cucumber': testAssessmentInfo.copyWith(jurisdiction: 'cucumber'),
            'banana': testAssessmentInfo.copyWith(jurisdiction: 'banana'),
            'apple': testAssessmentInfo.copyWith(jurisdiction: 'apple'),
            'dragonfruit': testAssessmentInfo.copyWith(
              jurisdiction: 'dragonfruit',
            ),
          },
          questionInfoMap: {},
          recommendationsInfoMap: {},
        ),
        expected: [
          ('apple', testAssessmentInfo.copyWith(jurisdiction: 'apple')),
          ('banana', testAssessmentInfo.copyWith(jurisdiction: 'banana')),
          ('cucumber', testAssessmentInfo.copyWith(jurisdiction: 'cucumber')),
          (
            'dragonfruit',
            testAssessmentInfo.copyWith(jurisdiction: 'dragonfruit'),
          ),
        ],
      ),
    ];

    for (final testCase in testCases) {
      // Arrange
      final staticData = testCase.staticData;
      // Act
      final result = staticData.assessmentInfoPairsSorted;
      // Assert
      expectEqual(result, testCase.expected);
    }
  });
  test('RecommendationCategory optionGroupCount and optionGroups', () {
    final List<
      ({
        RecommendationCategory category,
        List<({String? good, String? better, String? best})>
        expectedOptionGroups,
      })
    >
    testCases = [
      (
        category: RecommendationCategory(
          categoryTitle: 'cat0',
          goodHealth: ['good0', 'good1', 'good2'],
          betterHealth: ['better0', 'better1', 'better2'],
          bestHealth: ['best0', 'best1', 'best2'],
        ),
        expectedOptionGroups: [
          (good: 'good0', better: 'better0', best: 'best0'),
          (good: 'good1', better: 'better1', best: 'best1'),
          (good: 'good2', better: 'better2', best: 'best2'),
        ],
      ),
      (
        category: RecommendationCategory(
          categoryTitle: 'cat0',
          goodHealth: ['good0', 'good1', 'good2'],
          betterHealth: ['better0'],
          bestHealth: ['best0', 'best1', 'best2', 'best3'],
        ),
        expectedOptionGroups: [
          (good: 'good0', better: 'better0', best: 'best0'),
          (good: 'good1', better: null, best: 'best1'),
          (good: 'good2', better: null, best: 'best2'),
          (good: null, better: null, best: 'best3'),
        ],
      ),
      (
        category: RecommendationCategory(
          categoryTitle: 'cat0',
          goodHealth: [],
          betterHealth: [],
          bestHealth: ['best0', 'best1', 'best2', 'best3', 'best4'],
        ),
        expectedOptionGroups: [
          (good: null, better: null, best: 'best0'),
          (good: null, better: null, best: 'best1'),
          (good: null, better: null, best: 'best2'),
          (good: null, better: null, best: 'best3'),
          (good: null, better: null, best: 'best4'),
        ],
      ),
    ];

    for (final testCase in testCases) {
      // Arrange
      final cat = testCase.category;
      // Act
      final countResult = cat.optionGroupCount;
      final groupResult = cat.optionGroups;
      // Assert
      expectEqual(countResult, testCase.expectedOptionGroups.length);
      expectEqual(groupResult, testCase.expectedOptionGroups);
    }
  });

  test('AssessmentInfo.getQuestionInfos', () {
    // Arrange
    final List<
      ({
        AssessmentInfo assessmentInfo,
        Map<String, QuestionInfo> questionInfoMap,
        List<List<QuestionInfo>> expected,
      })
    >
    testCases = [
      (
        assessmentInfo: testStaticData1.assessmentInfoMap['ai1']!,
        questionInfoMap: testStaticData1.questionInfoMap,
        expected: [
          [
            testStaticData1.questionInfoMap['qi1']!,
            testStaticData1.questionInfoMap['qi2']!,
            testStaticData1.questionInfoMap['qi3']!,
          ],
          [
            testStaticData1.questionInfoMap['qi1']!,
            testStaticData1.questionInfoMap['qi2']!,
          ],
        ],
      ),
      (
        assessmentInfo: testStaticData1.assessmentInfoMap['ai2']!,
        questionInfoMap: testStaticData1.questionInfoMap,
        expected: [
          [
            testStaticData1.questionInfoMap['qi3']!,
            testStaticData1.questionInfoMap['qi2']!,
          ],
          [
            testStaticData1.questionInfoMap['qi3']!,
            testStaticData1.questionInfoMap['qi2']!,
            testStaticData1.questionInfoMap['qi1']!,
          ],
        ],
      ),
    ];

    for (final testCase in testCases) {
      // Act
      final result = testCase.assessmentInfo.getQuestionInfos(
        testCase.questionInfoMap,
      );

      // Assert
      expectEqual(result, testCase.expected);
    }
  });
}
